	(341, 'movie', 'akira', 'Akira', 1988, 149, '/5KlRFKKSbyCiyYpZSS3A6G5bW0K.jpg', 7, 'Too old for me', 'I needed to see it 10-15 years ago than maybe it would have been a masterpiece, but today it''s just fine. Visually it''s impressive as you think it was made in 1988, especially environments and action, but I just can''t stand how atrociously bad characters design look, it''s ugly as fuck.', '2021-05-02 18:58:22.7+00', '2021-11-02 15:06:31.449+00', '2021-05-02 18:58:22.7+00', 168, NULL, NULL, 'A'),
