	(356, 'series', 'the-rising-of-the-shield-hero', 'The Rising of the Shield Hero', 2019, 83095, '/6cXf5EDwVhsRv8GlBzUTVnWuk8Z.jpg', 9, 'Great first season', 'Hero gets humiliated to the extreme and now he doesn''t give a fuck about kingdom he suppose to save, only himself. Now he start rising with rage to the top.', '2021-03-01 07:17:55+00', '2022-04-25 12:56:45.364+00', '2021-03-01 07:17:55+00', 147, NULL, NULL, 'C'),
