	(494, 'movie', 'the-lord-of-the-rings-the-two-towers', 'The Lord of the Rings: The Two Towers', 2002, 121, '/5VTN0pR8gcqV3EPUHHfMGnJYN9L.jpg', 10, '', 'Already classic. Scenery and story is most amazing parts of the movie. Great action and war scenes. The extended version is a little bit too long, but I enjoyed every second anyway. Great, rewatch value.', '2018-02-18 19:00:04+00', '2026-11-16 10:37:31.86+00', '2018-02-18 19:00:04+00', NULL, 2, NULL, 'S'),
	(471, 'movie', 'spider-man-into-the-spider-verse', 'Spider-Man: Into the Spider-Verse', 2018, 324857, '/iiZZdoQBEYBv6id8su7ImL0oCbD.jpg', 10, 'Spectacular', 'One of the most amazing animations I have seen in recent history. The details, colors and story creates amazing mix of mastrrmising specticle.', '2019-01-07 09:05:52+00', '2026-11-16 10:37:58.925+00', '2019-01-04 00:00:00+00', NULL, 7, NULL, 'S'),
	(430, 'movie', 'the-dark-knight-rises', 'The Dark Knight Rises', 2012, 49026, '/vzvKcPQ4o7TjWeGIn0aGC9FeVNu.jpg', 9, '', 'Everything, what Christopher Nolan touch is a masterpiece.<br />  From Batman trilogy, this is my second favourite one after "The Dark Knight" (2008).<br />  I really love Christian Bale as Batman. he portrays him really well. I can''t stand Ben Affleck as new batman in newer DC movies.<br />  The only con of the movie is Bane. Even if Tom Hardy did really well and I loved acting and dialogue, but for me, he felt not as a big villain as Joker did in the last movie.', '2018-02-26 19:44:18+00', '2026-11-16 10:39:08.224+00', '2018-02-26 19:44:18+00', NULL, 16, NULL, 'S'),
	(402, 'movie', 'mandy', 'Mandy', 2018, 460885, '/m0yf7J7HsKeK6E81SMRcX8vx6mH.jpg', 10, 'Fucking spectacular!', 'Holy fuck! I have lost my thoughts about it from orgasmic spectacularness.<br />  That is one of the rare amazing movies I came across completely unexpected.<br />  It simply best in this category with stunning cinematography and slowly developing a thrilling story.<br />  Simply amazing.', '2018-11-23 18:44:22+00', '2026-11-16 10:39:27.516+00', '2018-11-23 00:00:00+00', NULL, 21, NULL, 'S'),
	(500, 'series', 'black-mirror-season-4', 'Black Mirror', 2017, 42009, '/pXeuSWSKgWUnhRFHZ4TjAUU8lbE.jpg', 8, 'must see, till certain point', 'Different non-connecting stories about wonders of new and near future technology and all hypothetical implementation of it, but mostly how it can go wrong. Pick any episode and just enjoy. Highly thought out smart stories, which will leave you thinking. Definitely one of my favorites, but unfortunately few latest seasons gets pretty bad.', '2018-01-03 20:52:02+00', '2026-11-16 10:43:08.351+00', '2017-12-30 00:00:00+00', NULL, NULL, 15, 'A'),
