	(278, 'series', 'kokoro-connect', 'Kokoro Connect', 2012, 45807, '/kzPbvHs9qISUPSQUbqnLdaiJh8E.jpg', 9, 'Unexpected find', 'What would you do if you start unexpectedly without any control swap bodies with your friends? Great story premise and how the story unfolds is just amazing to watch. The best part of the series is writing, while it''s very smartly written and told.', '2021-05-03 07:04:59.687+00', '2026-11-16 22:18:40.828+00', '2021-05-03 07:04:59.687+00', 118, NULL, NULL, 'A'),
