	(1065, 'series', 'kamikatsu-working-for-god-in-a-godless-world', 'KamiKatsu: Working for God in a Godless World', 2023, 199920, '/d82CH1EMSoC2VvYSTxCZHPboJYq.jpg', 4, 'Literal definition of trash anime', NULL, '2023-07-08 11:00:05.964166+00', '2023-07-08 11:00:43+00', '2023-07-08 23:00:05+00', 262, NULL, NULL, 'C'),
	(601, 'series', 'why-the-hell-are-you-here-teacher', 'Why the Hell are You Here, Teacher!?', 2019, 86836, '/1yss3gl6mMNT9Txvdtvnu2KTWt9.jpg', 7, 'A lot of Boobies', 'This Anime is on the borderline to crossing into Hentai and the strongest point is unexpected events in the story. I was shockingly surprised by what the director come up with. Don''t remember laughing so much in a long time.', '2022-02-13 13:00:12.019+00', '2022-03-07 08:11:24.602+00', '2022-02-13 13:00:12.019+00', 260, NULL, NULL, 'C'),
	(245, 'movie', 'edge-of-tomorrow', 'Edge of Tomorrow', 2014, 137113, '/uUHvlkLavotfGsNtosDy8ShsIYF.jpg', 10, 'Perfect Sci-Fi Action Thriller', 'I love time travel movies, and this one is with pretty interesting story. Acting of Tom Cruise in movie is perfect too.', '2016-08-13 10:09:07+00', '2026-11-16 10:37:45.256+00', '2016-08-13 10:09:07+00', NULL, 3, NULL, 'S'),
	(298, 'series', 'rezero-starting-life-in-another-world', 'Re:ZERO -Starting Life in Another World-', 2016, 65942, '/5DZa4aDH5MZGcZDf8ouTxm2kH2Y.jpg', 10, 'Love it', 'I loved the movie "Edge of Tomorrow" and any other movie or series that tries to show similar mechanics of reliving day after day is worth to try watching. And this anime showed that it can be done in the anime story. I''m not a huge fan of deep fantasy stories, but after seeing this series I might need to change my interests, while this story makes me badly want more. The story starts simply as its main character gets summoned from our world to the magical world, and as the story progresses, it gets way more philosophical, psychological and even mythological, showing what toll it can take on a person''s mind reliving the same previous point in time as you get back after dying with remembering everything that you did before. So far after 1 and a half-season, it stands very strongly on one of my favourites and I imagine it will get even more interesting as it will continue releasing new episodes.', '2020-10-04 22:57:00+00', '2025-03-26 23:24:10+00', '2025-03-26 23:00:00+00', 4, NULL, NULL, 'S'),
	(192, 'movie', 'moon', 'Moon', 2009, 17431, '/cJ6JnuLwCNbiAAOBuHDjRTP7bQJ.jpg', 9, '', 'I just liked everything what it is shown in this movie. Great pace of the movie, great thrilling story, great visuals. Really great sci-fi movie about space and human cloning.', '2017-04-14 22:13:16+00', '2026-11-16 10:37:54.262+00', '2017-04-14 22:13:16+00', NULL, 6, NULL, 'S'),
	(110, 'series', 'the-office', 'The Office', 2005, 2316, '/qWnJzyZhyy74gjpSjIXWmuk0ifX.jpg', 10, 'Hilarious and heartwarming. One of the best I have ever seen.', 'Finally decided to watch from beginning till end. It has everything from comedy till drama. It brings you to laugh and cry. One of the best TV shows in the history and I''m glad I decided to finally watch it.', '2020-04-24 15:23:42+00', '2026-11-16 10:39:58.398+00', '2020-04-24 15:23:42+00', NULL, NULL, 3, 'S'),
	(197, 'series', 'maniac', 'Maniac', 2018, 73411, '/kCNl4QPstAqChFD0NnLpbDFG8ul.jpg', 10, 'Unbelievably good', 'This Mini TV Series left me mouth open from amazement. The most amazing series in a long time.<br />  Very interesting original storytelling with some very bizarre, confusing elements. At some point you start thinking that nothing really makes sense, but you keep watching while it''s intriguing, and can''t stop till the end and get shocked how everything fits to it''s places. Outstanding acting of Emma Stone and Jonah Hill. Gorgeous cinematography, mystery and insanity at some point, keep you glued to the screen till the end. Simply Masterpiece of it''s kind.', '2018-09-25 19:12:04+00', '2026-11-16 10:40:27.451+00', '2018-09-25 00:00:00+00', NULL, NULL, 5, 'S'),
	(1160, 'series', 'flower-and-asura', 'Flower and Asura', 2025, 256744, '/8r6Fv7tNRVOH5uKf1rkj6sK8KWF.jpg', 8, 'Fine', NULL, '2025-03-25 18:59:00.190618+00', '2025-04-04 12:34:47+00', '2025-03-25 18:59:00+00', 144, NULL, NULL, 'B'),
