	(560, 'series', 'princess-connect-redive', 'Princess Connect! Re:Dive', 2020, 99084, '/rHijpbAPTlwLdtz5RWHwLWMyns4.jpg', 6, 'Holy Shit, how stupid is MC', 'If you replace main character with wooden log, it still would be smarter than this log. Only what saves this show are three supporting chapters around him.', '2021-11-03 13:20:06.218+00', '2026-11-16 22:17:20.388+00', '2021-09-24 22:00:00+00', 290, NULL, NULL, 'C'),
	(1139, 'series', 'failure-frame-i-became-the-strongest', 'Failure Frame: I Became the Strongest and Annihilated Everything with Low-Level Spells', 2024, 245285, '/jjpkWZ9LUXoUnh4F65qp7FuFawO.jpg', 3, 'Failure Show: How to Copy Other shows and Make It a Way Worse', 'Total trash show. Quality of animation and models atrocious. Wronged hero cliche. Overpowered ability of course. Slimes? Just why? Horse with wheels? Wtf? Bland generic companion. Enemies just one note bad with questionable morals. Cringe edge dialogue is just the worst. Watching anything, literally anything this was based off or copied from, will be a better investment of time than watching this.', '2024-09-18 07:15:12.800127+00', '2026-11-16 10:30:15.258+00', '2024-09-25 22:00:00+00', 299, NULL, NULL, 'F'),
	(20, 'series', 'horimiya', 'Horimiya', 2021, 110070, '/zLNnCb6SL2HxyiRsDJ4t4S1mb91.jpg', 8, 'Heartwarming and true', 'Great anime with one problem - there is no conflict in it, so it''s just only watching real life from the side, but that is not that bad.', '2021-03-01 18:14:25+00', '2026-11-16 10:32:54.489+00', '2021-03-01 18:14:25+00', 276, NULL, NULL, 'C'),
