	(1236, 'movie', 'only-the-brave', 'Only the Brave', 2017, 395991, '/db5IkOJu9UHktrKroNktw1Z8ARY.jpg', 9, 'Very good acting', '', '2026-10-03 16:13:35.332478+00', '2026-11-12 14:39:59+00', '2026-10-03 16:13:35+00', NULL, NULL, NULL, NULL),
	(60, 'series', 'the-americans', 'The Americans', 2013, 46533, '/qB7WPVQnmODg2mZ1xUmPOrCa0wL.jpg', 9, 'Better with each new season', 'I love the concept of the show. It''s a huge conflict, but it is just not as simple as "good guys" vs "bad guys", while the main characters of the show are Russian spies in the USA during the Cold War. So by a stereotypical view from an American viewer perspective, Russians should be bad ones, but the show wants you to root for them to succeed in all what they do, to make the world a better place. And with each season you raise ever more doubt of whos is "bad guys" in all of it, while both sides do horrible things to each other.<br />  A little bit slow and unsure in the beginning, but with each new season getting more amazing acting performance and deeper, more thrilling story development.', '2019-05-07 09:09:23+00', '2019-05-07 09:09:23+00', '2019-05-07 09:09:23+00', NULL, NULL, NULL, NULL),
	(61, 'movie', 'the-lego-movie-2-the-second-part', 'The Lego Movie 2: The Second Part', 2019, 280217, '/QTESAsBVZwjtGJNDP7utiGV37z.jpg', 8, 'Everything is awesome again!', NULL, '2019-04-28 20:09:05+00', '2019-04-28 20:09:05+00', '2019-04-28 00:00:00+00', NULL, NULL, NULL, NULL),
	(62, 'movie', 'bumblebee', 'Bumblebee', 2018, 424783, '/fw02ONlDhrYjTSZV8XO6hhU3ds3.jpg', 8, 'Enjoyed more than I should have', 'I definitely can say it''s not bad movie, because I really enjoyed watching it, even story is cheesey. It''s kind a same as the first movie in Transformers Franchise with almost same storytelling and feeling, so more likely I liked it because of nostalgia.', '2019-04-04 20:04:04+00', '2019-04-04 20:04:04+00', '2019-04-04 00:00:00+00', NULL, NULL, NULL, NULL),
