	(101, 'movie', 'greyhound', 'Greyhound', 2020, 516486, '/kjMbDciooTbJPofVXgAoFjfX8Of.jpg', 5, 'Simply war movie', 'A pretty standard war movie, what doesn''t do anything new what other WW2 movies haven''t done before. The story is somewhat captivating and keeps momentum till the end unless you take a break and then you lose interest very quickly. Pretty nice cinematography and visual effects, but the weak story.', '2020-08-09 12:04:01+00', '2020-08-09 12:04:01+00', '2020-08-09 12:04:01+00', NULL, NULL, NULL, NULL),
