	(295, 'series', 'rascal-does-not-dream-of-bunny-girl-senpai', 'Rascal Does Not Dream of Bunny Girl Senpai', 2018, 82739, '/cU4jHfo1Q9AEPnFqFqtuSA74gdi.jpg', 8, 'Good story', NULL, '2020-11-29 19:27:29+00', '2021-11-02 15:09:10.189+00', '2020-11-29 19:27:29+00', 76, NULL, NULL, 'B'),
	(89, 'series', 'steinsgate-the-sagacious-wisdom-of-cognitive-computing', 'Steins;Gate', 2014, 42509, '/opIMHHP3eeQhWoKXKzfayR9mqqB.jpg', 9, 'Great story', 'One thing I can''t pass on is storys that involves Time travel, so I''m definitely need to watch this one too and by surprise it''s something amazing. Story development is incredible well written and it has just perfect atmosphere for events happening around. It''s also do not get too much into fantasy setting and tries to keep real world perspective, what is really pleasant surprise in sciences fiction anime.', '2020-11-05 11:59:38+00', '2021-11-02 15:09:26.716+00', '2020-11-05 11:59:38+00', 123, NULL, NULL, 'A'),
