	(121, 'movie', '6-underground', '6 Underground', 2019, 509967, '/lnWkyG3LLgbbrIEeyl5mK5VRFe4.jpg', 6, NULL, 'Michael Bay movie, so of course a lot of cool action scenes and many unnecessary splashy explosions, a problem like with Transformers movies - horribly bad and silly story.', '2020-01-19 14:55:50+00', '2020-01-19 14:55:50+00', '2020-01-19 14:55:50+00', NULL, NULL, NULL, NULL),
	(122, 'movie', 'ad-astra', 'Ad Astra', 2019, 419704, '/xJUILftRf6TJxloOgrilOTJfeOn.jpg', 8, 'Spectacular', 'Something like Interstellar, only without black holes and love as a force for everything, instead down to earth science and plain story in space.', '2019-12-05 22:20:39+00', '2019-12-05 22:20:39+00', '2019-12-05 00:00:00+00', NULL, NULL, NULL, NULL),
