	(1133, 'movie', 'violet-evergarden-the-movie', 'Violet Evergarden: The Movie', 2020, 533514, '/A9R6bukzzRmOzxvDQsXdQpeNm8l.jpg', 10, 'Hearth wrenching finale', '', '2024-09-01 16:34:44.606523+00', '2026-11-16 22:06:32.606+00', '2024-09-01 16:34:44+00', 25, NULL, NULL, 'A'),
	(125, 'series', 'the-man-in-the-high-castle-season-3', 'The Man in the High Castle', 2015, 62017, '/xhoDZbMNeyCA0BGPZQsdIiO43Dp.jpg', 5, 'Some good episodes, but way too slow story development. In general disappointing.', 'Series has few really good episodes, but everything else is the way too slow going with a lot of unnecessary scenes. Could be more action-packed. There is opposition in a story and I more love the storyline of nazi''s side, while is way more interesting than resistance. At the end of this season, you feel like you haven''t moved much forward, still sitting waiting for something exciting to happen and it just ends with a big cliffhanger.<br />  Last season delivers some interesting story development, but it gets a bit undeveloped and not very well utilised and ending with pretty quick meaningless ending of tv series. I am disappointed.', '2019-11-17 09:42:47+00', '2019-11-17 09:42:47+00', '2018-10-07 00:00:00+00', NULL, NULL, NULL, NULL),
	(126, 'series', 'elite', 'Elite', 2018, 76669, '/3NTAbAiao4JLzFQw6YxP1YZppM8.jpg', 7, 'With each season is more cringe', NULL, '2019-11-10 12:19:30+00', '2022-04-19 06:35:21.423+00', '2022-04-15 22:00:00+00', NULL, NULL, NULL, NULL),
	(127, 'movie', 'black-mirror-bandersnatch', 'Black Mirror: Bandersnatch', 2018, 569547, '/fR0VZ0VE598zl1lrYf7IfBqEwQ2.jpg', 9, 'Ha, let''s try again', NULL, '2019-11-09 20:00:11+00', '2019-11-09 20:00:11+00', '2019-11-09 20:00:11+00', NULL, NULL, NULL, NULL),
	(128, 'series', 'the-end-of-the-fing-world_s01', 'The End of the F***ing World', 2017, 74577, '/xzwwzmXbz6n2Y3fc0GbjqGiFQPm.jpg', 10, 'Me:"Briliant" Also me:"OK"', 'The dialogue in this TV Series is just brilliant - everything is just few words, one line. Acting is also awkward intentional and it makes most of the time lough. Never seen such a show. Simply brilliant.', '2019-11-06 20:23:34+00', '2019-11-06 20:23:34+00', '2018-01-13 00:00:00+00', NULL, NULL, NULL, NULL),
	(129, 'series', 'watchmen', 'Watchmen', 2019, 79788, '/m8rWq3j73ZGhDuSCZWMMoE9ePH1.jpg', 8, 'So many questions', NULL, '2019-10-23 20:04:20+00', '2019-10-23 20:04:20+00', '2019-10-23 20:04:20+00', NULL, NULL, NULL, NULL),
	(130, 'series', 'doom-patrol', 'Doom Patrol', 2019, 79501, '/nVN7Dt0Xr78gnJepRsRLaLYklbY.jpg', 10, 'Love it', 'Something special from DC comics. Even story at some points is ridiculously silly and bit dumb, but it has way very interesting stories about the emotional struggle of each character, what pushes this TV series very high on my radar.  In 50 min. it shows so much more character development than any other recent DC superhero movie like Suicide Squad or Justice League.', '2019-10-14 19:56:38+00', '2019-10-14 19:56:38+00', '2019-10-14 19:56:38+00', NULL, NULL, NULL, NULL),
	(131, 'movie', 'el-camino-a-breaking-bad-movie', 'El Camino: A Breaking Bad Movie', 2019, 559969, '/ePXuKdXZuJx8hHMNr2yM4jY2L7Z.jpg', 9, 'Nice ending', 'It like missing last episode from TV series. Unnecessary closure, but I really was happy get back to Breaking Bad universe.', '2019-10-12 16:34:09+00', '2019-10-12 16:34:09+00', '2019-10-12 16:34:09+00', NULL, NULL, NULL, NULL),
