	(155, 'movie', 'skyscraper', 'Skyscraper', 2018, 447200, '/5LYSsOPzuP13201qSzMjNxi8FxN.jpg', 4, 'Full of stereotypical cliches', 'Takeaway from whole movie:<br />  "If you can''t fix it with duct tape, you''re not using enough duct tape." :D', '2018-09-27 19:14:35+00', '2018-09-27 19:14:35+00', '2018-09-27 00:00:00+00', NULL, NULL, NULL, NULL),
	(156, 'movie', 'solo-a-star-wars-story', 'Solo: A Star Wars Story', 2018, 348350, '/3IGbjc5ZC5yxim5W0sFING2kdcz.jpg', 8, 'Enjoyed way more than expected', 'I was expecting way worse movie, than it actually was. It way better and more entertaining than <b>Rogue One: A Star Wars Story</b>.<br />  It don''t show anything shockingly new, but action is great, visuals is also stunningly good. Story little bit weak, but still entertaining.', '2018-09-13 20:44:14+00', '2018-09-13 20:44:14+00', '2018-09-13 00:00:00+00', NULL, NULL, NULL, NULL),
	(157, 'movie', 'american-animals', 'American Animals', 2018, 489931, '/aLbdKxgxuOPvs6CTlmzoOQ4Yg3j.jpg', 6, 'Decent', 'The heist movie with a story based on true facts, even with people telling a story from their own lips. It''s interesting because it could be simply just a documentary, but it''s a reenactment of the whole story with a cinematographical view. It''s a fine movie with moral in it, but that''s nothing more.', '2018-09-05 09:52:01+00', '2018-09-05 09:52:01+00', '2018-09-04 00:00:00+00', NULL, NULL, NULL, NULL),
