	(183, 'movie', 'pirates-of-the-caribbean-dead-men-tell-no-tales', 'Pirates of the Caribbean: Dead Men Tell No Tales', 2017, 166426, '/xbpSDU3p7YUGlu9Mr6Egg2Vweto.jpg', 7, 'Still good time watching, but it''s get''s boring already.', 'Still entertaining to watch, but the story gets way too much exhausted.<br />  It''s getting repetitive with each new movie from this franchise.<br />  They should just finish it or change something completely.', '2017-09-09 15:13:29+00', '2017-09-09 15:13:29+00', '2017-09-09 00:00:00+00', NULL, NULL, NULL, NULL),
