	(189, 'movie', 'ghost-in-the-shell-2', 'Ghost in the Shell', 2017, 315837, '/myRzRzCxdfUWjkJWgpHHZ1oGkJd.jpg', 7, NULL, 'Nice, but don''t know if would watch it again. Original anime is better looking and more interesting. In the movie is just little bit too much CGI.', '2017-07-15 19:30:25+00', '2017-07-15 19:30:25+00', '2017-07-15 19:30:25+00', NULL, NULL, NULL, NULL),
	(191, 'movie', 'raid-2', 'The Raid 2', 2014, 180299, '/olA39iaXISiKEkACdELgr0ZRvIF.jpg', 8, NULL, 'It''s really an interesting sequel and I could say even very successful. They chose completely new kind of style of storytelling, which is more complex and that is a great choice. Something new and not repeating the first one. Only the action is great as first, but that is a huge plus.', '2017-05-15 15:00:29+00', '2017-05-15 15:00:29+00', '2017-05-15 15:00:29+00', NULL, NULL, NULL, NULL),
	(193, 'movie', 'the-raid-redemption', 'The Raid', 2012, 94329, '/Abnm1Ws3JH0ReCfEhLMPwPcMcGO.jpg', 8, NULL, 'Great action scenes and martial arts.', '2017-04-12 21:37:16+00', '2017-04-12 21:37:16+00', '2017-04-12 21:37:16+00', NULL, NULL, NULL, NULL),
	(194, 'movie', 'venom', 'Venom', 2018, 335983, '/2uNW4WbgBXL25BAbXGLnLqX71Sw.jpg', 5, 'Visually stunning, story-wise dumb', 'Don''t know what to say. It''s not great, but not so so horrible too.<br />  Visually it''s amazing. CGI is top on this movie, especially fighting scenes is fluid and full of details.<br />  But movie suffers from really bad story script, there are so much cheese cliches that don''t get well and motivations what it don''t have any support except "just because". In comix, it would be fine, but in the real action movie, it simply looks dumb and out of place, not even comedic, plain dumb.', '2018-11-28 19:35:49+00', '2018-11-28 19:35:49+00', '2018-11-28 00:00:00+00', NULL, NULL, NULL, NULL),
	(195, 'series', 'deutschland-86', 'Deutschland', 2018, 62681, '/s9XficGcBL9Gv0LZNPGESjnDFEA.jpg', 8, 'Great', NULL, '2018-11-17 12:14:30+00', '2018-11-17 12:14:30+00', '2018-11-16 00:00:00+00', NULL, NULL, NULL, NULL),
	(196, 'series', 'peaky-blinders-s01-s03', 'Peaky Blinders', 2013, 60574, '/6PX0r5TRRU5y0jZ70y1OtbLYmoD.jpg', 10, 'Extraordinary good! Highly recommended!', 'Wonderful Tv Series about British "mafia" development from early years till peak and fall.<br />  Atmosphere, visuals and sound are simply amazing. A story full of surprises and twists along the way. Great character development and outstanding acting. The format of 6 episodes per Season is just perfect like each season is just a long movie!<br />  First, two seasons takes on the earlier years and shows rising of Peaky Blinders, the third season is get''s a little bit faster ahead and takes time to adjust to new changes, but in middle of the third season, the Peaky Blinders at it''s the best intrigue again.<br />  The fourth season continues from third and not a bit lost of interest.<br />  Writing is simply amazing. Now looking for the next season next year.', '2018-10-10 17:47:27+00', '2018-10-10 17:47:27+00', '2018-10-09 00:00:00+00', NULL, NULL, NULL, NULL),
	(190, 'movie', 'ex-machina', 'Ex Machina', 2015, 264660, '/9goPE2IoMIXxTLWzl7aizwuIiLh.jpg', 9, '', '', '2017-05-15 15:41:48+00', '2026-11-16 10:39:15.599+00', '2017-05-15 15:41:48+00', NULL, 18, NULL, 'A'),
