	(210, 'movie', 'isle-of-dogs', 'Isle of Dogs', 2018, 399174, '/c0nUX6Q1ZB0P2t1Jo6EeFSVnOGQ.jpg', 9, 'Originally good', 'The amazing cinematography of stop-motion animation and wonderful style.', '2018-06-23 16:16:08+00', '2018-06-23 16:16:08+00', '2018-06-23 00:00:00+00', NULL, NULL, NULL, NULL),
	(211, 'movie', 'everest', 'Everest', 2015, 253412, '/4xmndWnTYTE4bDdlWrkZyaGcZlo.jpg', 7, 'Good', NULL, '2018-06-18 12:47:43+00', '2018-06-18 12:47:43+00', '2018-06-18 12:47:43+00', NULL, NULL, NULL, NULL),
	(212, 'movie', 'tomb-raider', 'Tomb Raider', 2018, 338970, '/3zrC5tUiR35rTz9stuIxnU1nUS5.jpg', 8, 'Pretty good', 'Alicia Vikander as Lara Croft is a nice choice and very fitting role.<br />  I can definitely say I enjoyed this movie way more than Angelina''s Jolie movie.<br />  I liked the story even there are few cheesy moments, but a movie about computer game character in unbelievable adventures, this movie portrays it well. Really enjoyable action-packed movie.<br />  Indiana Jones in female form.', '2018-06-10 19:32:09+00', '2018-06-10 19:32:09+00', '2018-06-10 00:00:00+00', NULL, NULL, NULL, NULL),
	(214, 'series', 'lost-in-space_s01', 'Lost in Space', 2018, 75758, '/83mK4CnvRPFSqcyO3s3lq6aDy1x.jpg', 3, 'Towards end i lost insterest 😉', NULL, '2018-05-09 23:03:53+00', '2023-06-19 12:32:46+00', '2018-05-06 12:00:00+00', NULL, NULL, NULL, NULL),
	(215, 'movie', 'game-night', 'Game Night', 2018, 445571, '/85R8LMyn9f2Lev2YPBF8Nughrkv.jpg', 6, 'Decent comedy', NULL, '2018-05-09 23:01:20+00', '2018-05-09 23:01:20+00', '2018-05-09 00:00:00+00', NULL, NULL, NULL, NULL),
	(217, 'movie', 'the-lord-of-the-rings-the-return-of-the-king', 'The Lord of the Rings: The Return of the King', 2003, 122, '/rCzpDGLbOoPwLjy3OAm5NUPOTrC.jpg', 9, NULL, NULL, '2018-04-01 18:00:54+00', '2018-04-01 18:00:54+00', '2006-04-22 00:00:00+00', NULL, NULL, NULL, NULL),
	(218, 'movie', 'the-titan', 'The Titan', 2018, 476926, '/qRmQazyIBZR4pQIk9VruiZul0Au.jpg', 7, 'Interesting idea, but with few flaws', 'A really interesting plot of the movie, but it''s hard to decide if it a good movie or not.<br />  On one hand, it''s pretty original science fiction story of the near future, and ''Nazi'' like experiments to make human race better and even surpass its limitation for future generations to conquer other planets for the survival.<br />  But on other hands, there are few things in the story, what makes some aspects of the whole story little bit ridiculous and not well thought out.<br />  So I can say it''s visually and story wise intriguing movie, with good pace and character development, but at the end, I was left with the fought - ''what was the point of all of that?'', even in the back of the mind I kinda find the answer, but anyway I can only hypothesise the point of the movie, what maybe was the point in the movie. I don''t know. Enjoyable movie for science fiction fans, with few flaws in the story.', '2018-03-30 21:55:23+00', '2018-03-30 21:55:23+00', '2018-03-30 00:00:00+00', NULL, NULL, NULL, NULL),
	(219, 'movie', 'game-over-man', 'Game Over, Man!', 2018, 456750, '/58BnnYeQOTzdMBghZIH1tSH0REx.jpg', 2, 'Nope', NULL, '2018-03-30 19:27:15+00', '2018-03-30 19:27:15+00', '2018-03-30 00:00:00+00', NULL, NULL, NULL, NULL),
