	(220, 'movie', 'borg-mcenroe', 'Borg McEnroe', 2017, 397538, '/9jdg8VxleYb1DhPiEfHM7DzfvGw.jpg', 8, 'Really nice', 'Haven''t expected much from it, but I was nicely surprised how intriguing story it has. I didn''t know these two famous tennis players before watching a movie so I can say movie shows a great way of introducing and building characters. At one point I didn''t even know for which one I''m rooting more to win. The great conflict between.', '2018-03-24 21:01:16+00', '2018-03-24 21:01:16+00', '2018-02-18 00:00:00+00', NULL, NULL, NULL, NULL),
	(221, 'movie', '2001-2', '2001: A Space Odyssey', 1968, 62, '/ve72VxNqjGM69Uky4WTo2bK6rfq.jpg', 5, NULL, 'Maybe if I would have seen this movie 10 or more years ago, I would have loved it more, but after seeing so much other movies who stole ideas from this one, I found it a little bit disappointing.<br />  And I have very mixed feeling about the pacing of the movie, from one side I like it that it''s so slow, it goes well with music, but from another side, I hate it, while it takes way "WAY" too long for them to show some simple idea.<br />  The story is kinda simple, with lots of place for your own interpretation, like the most interpretation power requiring ending of the movie.<br />  A lot of people see this movie as a masterpiece, but for me (because maybe I''m too young) is just an old time, slow pace, slightly impressive movie.<br />  It doesn''t go on my favourite movies list.', '2018-02-11 15:30:24+00', '2018-02-11 15:30:24+00', '2018-02-11 15:30:24+00', NULL, NULL, NULL, NULL),
	(222, 'movie', 'what-happened-to-monday', 'What Happened to Monday', 2017, 406990, '/o6EsOqITcSzcdwD1zxBM9imdxjr.jpg', 6, 'Not special', '<i>"A story about future, when the world gets overpopulated, and one-child policy is the law, seven sisters got raised by one smart man in secret, but one day one sister disappears and others tries to find her."</i><br />  I would say generic action movie for wasting time. It had interesting story development in the beginning but falls short as it progresses. A lot of story holes and unbelievable actions. Kinda pointless in the end and no message behind.', '2018-01-02 15:06:41+00', '2018-01-02 15:06:41+00', '2018-01-02 00:00:00+00', NULL, NULL, NULL, NULL),
	(223, 'movie', 'austin-powers-international-man-of-mystery', 'Austin Powers: International Man of Mystery', 1997, 816, '/qSvfLwdDBLjZaPwA7qdn0yYePq5.jpg', 6, 'Fun', NULL, '2017-12-29 11:31:08+00', '2017-12-29 11:31:08+00', '2017-12-31 00:00:00+00', NULL, NULL, NULL, NULL),
