	(230, 'movie', 'baby-driver', 'Baby Driver', 2017, 339403, '/dN9LbVNNZFITwfaRjl4tmwGWkRg.jpg', 8, 'Entertaining', 'Great music and wonderful action scenes. A Little bit cheesy love story and some very weird character moral choices in some situations, but very highly enjoyable movie.', '2017-09-17 21:06:40+00', '2017-09-17 21:06:40+00', '2017-09-17 00:00:00+00', NULL, NULL, NULL, NULL),
	(231, 'movie', '557', 'Wonder Woman', 2017, 297762, '/gfJGlDaHuWimErCr5Ql0I8x9QSy.jpg', 8, 'Highly entertaining', 'Really entertaining movie. Great acting too.<br />  DC universe maybe still have its chance to shine.<br />  Acting and action are wonderfull. Story too. Only at the end is little bit too much CGI in last battle, but thought out the whole movie is a really great story.<br />  Really looking forward seeing more good new DC movies, <del>but really doubt</del> <i>I''m sure</i> that <a>"Justice League"</a> <del>will</del> <i>won''t</i> be anywhere close to this movies success and interest. <del>Time will show</del>. <i><strong>Update: </strong>I was fucking right - next movie is complete garbage.</i>', '2017-09-16 20:12:16+00', '2017-09-16 20:12:16+00', '2017-09-16 20:12:16+00', NULL, NULL, NULL, NULL),
	(232, 'movie', 'transformers-the-last-knight', 'Transformers: The Last Knight', 2017, 335988, '/s5HQf2Gb3lIO2cRcFwNL9sn1o1o.jpg', 1, 'Just don''t....', 'The same as Fast and Furious. I just keep watching, but after the movie, I felt wrong for doing that.<br />  Stupid entertainment without any value whatsoever.<br />  They keep milking this cow, even it''s looks like it was dead for a while. They need to keep this franchise alone to rest.', '2017-09-14 13:01:55+00', '2017-09-14 13:01:55+00', '2017-09-13 00:00:00+00', NULL, NULL, NULL, NULL),
