	(288, 'series', 'invincible', 'Invincible', 2021, 95557, '/yDWJYRAwMNKbIYT8ZB33qy84uzO.jpg', 8, 'Great', 'It definitely goes over the limit of the shown violence and gore in animation, but the thing that makes stand out from other "over top violence" shows is a fitting story and amazing voice acting. Interesting to see how far it will go and what comes next.', '2021-04-02 21:01:02+00', '2025-03-20 20:43:05+00', '2025-03-12 23:00:00+00', NULL, NULL, NULL, NULL),
