	(19, 'series', 'sword-art-online', 'Sword Art Online', 2012, 45782, '/nc33LuqbsT0g2NYcVTVaMLsvbXu.jpg', 7, 'Half ass good', 'Started strong, but at the end of the first season started sliding down to the boredom zone. Way too illogical. The funniest part that even the villain forgets what he does anything for.', '2021-03-10 23:14:56+00', '2026-11-16 22:19:03.255+00', '2021-03-10 23:14:56+00', 241, NULL, NULL, 'B'),
