	(360, 'series', 'extracurricular', 'Extracurricular', 2020, 90814, '/oXpSVePUISiI2uxj3OiUeyHsVQM.jpg', 8, 'Surprisingly good', 'Surprisingly good Korean series about student and his side job as "Pimp". Because series is Korean, it takes a bit different approach to the story that I would expect from american counterpart, that''s why it manages to surprise multiple times with narrative and character development.<br />  Social distant and best student in class to survive living alone from bad parents and save money for future studies, manages to run escort service, what even includes providing underage girls. Everything works fine until classmate finds out about his work and wants to join as partner.', '2021-01-10 21:59:58+00', '2021-01-10 21:59:58+00', '2021-01-10 21:59:58+00', NULL, NULL, NULL, NULL),
	(373, 'movie', 'archive', 'Archive', 2020, 606234, '/eDnHgozW8vfOaLHzfpHluf1GZCW.jpg', 9, 'Awesome', 'Cinematography and scenes design reminded me of the movie Moon (2009) only this story takes place on future earth. The story deals with one topic I really love - Artificial Intelligence, but it''s not the only thing what this movie is about, and it has some delightful surprises. Highly recommend seeing.', '2020-08-16 20:05:13+00', '2026-11-16 10:39:18.865+00', '2020-08-16 20:05:13+00', NULL, 19, NULL, 'A'),
	(355, 'series', 'mushoku-tensei-jobless-reincarnation', 'Mushoku Tensei: Jobless Reincarnation', 2021, 94664, '/1mFnzilCyj9Coa9jbN8vFYLEZdW.jpg', 10, 'Perfect in everything', 'Grandfather of Modern Isekai.  Masterpiece, with reason to be, while storywise it stands out from any other Isekai series by telling the story so smartly in such a way it feels believable. Every main character is complex with it''s own motivation and view of the world, so you can''t simply judge just from first impressions and need time to learn about them. But the most shocking thing is details and love from creators and artists to everything you see in this new magical world they tell you about.', '2021-03-11 07:34:52+00', '2026-11-16 09:06:18.577+00', '2024-06-30 21:00:00+00', 3, NULL, NULL, 'S'),
	(363, 'movie', 'tenet', 'Tenet', 2020, 577922, '/k68nPLbIST6NP96JmTxmZijEvCA.jpg', 8, 'Dry action', NULL, '2020-12-05 16:51:11+00', '2020-12-05 16:51:11+00', '2020-12-05 16:51:11+00', NULL, NULL, NULL, NULL),
	(364, 'movie', 'love-and-monsters', 'Love and Monsters', 2020, 590223, '/r4Lm1XKP0VsTgHX4LG4syAwYA2I.jpg', 9, 'light heated, well made', 'This movie exactly everything that makes it work - the story is simple but well written and good paced, relatable characters and its development is perfect, no unnecessary plots. Simply enjoyable to watch.', '2020-11-01 11:35:41+00', '2020-11-01 11:35:41+00', '2020-11-01 11:35:41+00', NULL, NULL, NULL, NULL),
