	(589, 'movie', 'goblin-slayer-goblins-crown', 'Goblin Slayer: Goblin''s Crown', 2020, 631132, '/oyDaF4za9C9GxfYSyZUmj2aZGJT.jpg', 7, 'Still the best goblin is dead goblin', 'Good continuation of series.  Only the first 20min is unnecessary to see if you have seen a series recently while it''s a recap of the story so far. Afterward is pure joy.', '2022-01-03 21:27:42.231+00', '2026-11-16 22:16:02.938+00', '2022-01-03 21:27:42.231+00', 161, NULL, NULL, 'C'),
