	(437, 'movie', 'rememory', 'Rememory', 2017, 395814, '/qz3mvkpTOQOEqzxenvaaObOMarj.jpg', 5, 'Good, but not special', 'The story hasn''t felt very original somehow, it felt like taken parts from few other movies and tv series (like "black mirror"), but for a one-time watch is an enjoyable crime drama.', '2017-11-16 21:13:54+00', '2017-11-16 21:13:54+00', '2017-11-16 00:00:00+00', NULL, NULL, NULL, NULL),
