	(479, 'movie', 'blade-runner-2049', 'Blade Runner 2049', 2017, 335984, '/gajva2L0rPYkEWjzgFlBXCAVBE5.jpg', 10, 'must see!', 'A well-made movie with extraordinary visual style and atmosphere.  Great acting and very captivating story. If you enjoyed the original blade runner movie, this sequel gives the same goosebumps watching it. Very exciting.', '2018-07-15 20:04:19+00', '2018-07-15 20:04:19+00', '2017-12-28 00:00:00+00', NULL, NULL, NULL, NULL),
